import numpy as np


class AdaptiveMixedSearchV12:
    """
    Batched mixed-integer (mu+lambda) ES with:
    - Continuous genes in [0,1] mapped to bounds; discrete genes as integer labels.
    - Duplicate cache (no budget used for repeated points) and strict budget guard.
    - Probability-matched operator selection (DE best-guided, DE rand, Gaussian, crossover).
    - Per-coordinate continuous pattern steps (doubling on success, halving on failure),
      persistent across restarts; pattern search repeats while it keeps improving.
    - IPOP-style population growth on restarts, so later runs explore more broadly.
    - Restarts cycling through incumbent-seeded (multi-scale, shrinking), archive-seeded and LHS random.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float).reshape(-1)
        ub = np.asarray(func.bounds.ub, dtype=float).reshape(-1)
        vt = np.array([str(v) for v in func.variable_types])

        is_cont = vt == "continuous"
        is_bin = vt == "binary"
        is_ord = vt == "ordinal"
        is_disc = ~is_cont

        nv = np.ones(d)
        if getattr(func, "n_values", None) is not None:
            raw = np.asarray(func.n_values, dtype=float).reshape(-1)
            nv[is_disc] = raw[is_disc]
        nv[is_bin] = 2
        nv = np.maximum(nv, 1).astype(int)

        cont = np.where(is_cont)[0]
        disc = np.where(is_disc)[0]
        ncont, ndisc = len(cont), len(disc)
        pm = min(0.5, 1.5 / max(ndisc, 1)) if ndisc > 0 else 0.0

        self.calls = 0
        best_y = np.inf
        best_x = None
        best_g = None
        cache = {}
        archive = []
        attempts = 0
        max_attempts = 50 * self.budget + 1000
        step = np.full(ncont, 0.1)

        def decode(g):
            x = np.empty(d)
            if ncont:
                x[cont] = lb[cont] + g[cont] * (ub[cont] - lb[cont])
            if ndisc:
                x[disc] = np.round(g[disc])
            return x

        def key_of(g):
            k = []
            if ncont:
                k.extend(np.round(g[cont], 9).tolist())
            if ndisc:
                k.extend(np.round(g[disc]).astype(int).tolist())
            return tuple(k)

        def update_archive(y, g):
            kg = key_of(g)
            for _, ga in archive:
                if key_of(ga) == kg:
                    return
            archive.append((y, g.copy()))
            archive.sort(key=lambda t: t[0])
            del archive[12:]

        def eval_batch(G):
            nonlocal best_y, best_x, best_g, attempts
            res = [None] * len(G)
            pend = {}
            todo, tkeys, slots = [], [], []
            for i, g in enumerate(G):
                attempts += 1
                k = key_of(g)
                if k in cache:
                    res[i] = cache[k]
                    continue
                if k in pend:
                    slots.append((i, k))
                    continue
                if self.calls + len(todo) >= self.budget:
                    continue
                pend[k] = len(todo)
                todo.append(g.copy())
                tkeys.append(k)
                slots.append((i, k))
            if todo:
                X = np.array([decode(g) for g in todo])
                Y = np.asarray(func(X), dtype=float).reshape(-1)
                for j, g in enumerate(todo):
                    y = float(Y[j])
                    cache[tkeys[j]] = y
                    self.calls += 1
                    if y < best_y:
                        best_y, best_x, best_g = y, X[j].copy(), g.copy()
                    update_archive(y, g)
                for i, k in slots:
                    if k in cache:
                        res[i] = cache[k]
            return res

        def random_pop(n):
            G = np.empty((n, d))
            for j in cont:
                perm = np.random.permutation(n)
                G[:, j] = (perm + np.random.rand(n)) / n
            if ndisc:
                G[:, disc] = np.random.randint(0, nv[disc], size=(n, ndisc))
            return G

        def mutate_disc(g, rate):
            for j in disc:
                if np.random.rand() >= rate:
                    continue
                n = nv[j]
                if n <= 1:
                    continue
                k = int(round(g[j]))
                if is_bin[j]:
                    g[j] = 1 - k
                elif is_ord[j]:
                    if np.random.rand() < 0.15:
                        g[j] = np.random.randint(n)
                    else:
                        cand = [v for v in (k - 1, k + 1) if 0 <= v < n]
                        g[j] = cand[np.random.randint(len(cand))]
                else:
                    r = np.random.randint(n - 1)
                    g[j] = r if r < k else r + 1

        def perturb(g, scale):
            c = g.copy()
            if ncont:
                c[cont] = np.clip(c[cont] + scale * np.random.randn(ncont), 0.0, 1.0)
            mutate_disc(c, min(0.5, max(pm, 0.5 / max(ndisc, 1))))
            return c

        def pattern(g0, y0, rounds=3):
            # Per-coordinate adaptive continuous moves + discrete neighbourhood.
            g_cur, y_cur = g0.copy(), y0
            for _ in range(rounds):
                if self.calls >= self.budget:
                    break
                cands, meta = [], []
                for jj, j in enumerate(cont):
                    for s in (-1.0, 1.0):
                        c = g_cur.copy()
                        c[j] = np.clip(c[j] + s * step[jj], 0.0, 1.0)
                        cands.append(c)
                        meta.append(("c", jj))
                for j in disc:
                    n = nv[j]
                    if n <= 1:
                        continue
                    k = int(round(g_cur[j]))
                    if is_bin[j] or is_ord[j]:
                        for v in (k - 1, k + 1):
                            if 0 <= v < n:
                                c = g_cur.copy()
                                c[j] = v
                                cands.append(c)
                                meta.append(("d", j))
                    else:
                        for v in range(n):
                            if v != k:
                                c = g_cur.copy()
                                c[j] = v
                                cands.append(c)
                                meta.append(("d", j))
                if not cands:
                    break
                ys = eval_batch(cands)

                if ncont:
                    succ_c = np.zeros(ncont, dtype=bool)
                    for (kind, jj), y in zip(meta, ys):
                        if kind == "c" and y is not None and y < y_cur - 1e-12:
                            succ_c[jj] = True
                    step[succ_c] = np.minimum(step[succ_c] * 2.0, 0.5)
                    step[~succ_c] = np.maximum(step[~succ_c] * 0.5, 1e-4)

                best_i, best_v = None, y_cur
                for i, y in enumerate(ys):
                    if y is not None and y < best_v - 1e-12:
                        best_v, best_i = y, i
                if best_i is None:
                    break
                g_cur, y_cur = cands[best_i].copy(), best_v
            return g_cur, y_cur

        P0 = max(10, 3 * d)
        restarts = 0
        while self.calls < self.budget and attempts < max_attempts:
            calls_before = self.calls
            # IPOP-style growth: population doubles every full cycle of 4 restart modes.
            P = min(P0 * (2 ** (restarts // 4)), 200)
            n0 = min(P, self.budget - self.calls)
            if n0 <= 0:
                break

            mode = restarts % 4
            if restarts == 0 or best_g is None:
                G = random_pop(n0)
            elif mode == 0:
                G = random_pop(n0)
                scale = float(np.random.choice([0.02, 0.1, 0.25]))
                for i in range(n0 // 2):
                    G[i] = perturb(best_g, scale)
            elif mode == 1 and archive:
                G = random_pop(n0)
                for i in range(min(n0, len(archive))):
                    G[i] = perturb(archive[i][1], 0.1)
            elif mode == 3:
                G = random_pop(n0)
                shrink = 0.01 / (1 + restarts // 4)
                for i in range(n0 // 2):
                    G[i] = perturb(best_g, max(shrink, 1e-3))
            else:
                G = random_pop(n0)

            res = eval_batch(G)
            pop = [(y, g) for g, y in zip(G, res) if y is not None]
            if not pop:
                break

            sigma = float(np.random.choice([0.05, 0.15, 0.3]))
            op_succ = np.ones(4)
            stall = 0
            swept = False
            pop.sort(key=lambda t: t[0])
            run_best = pop[0][0]

            while self.calls < self.budget and stall < 15 and sigma > 1e-3 and attempts < max_attempts:
                pop.sort(key=lambda t: t[0])
                pop = pop[:P]
                m = max(2, len(pop) // 3)
                probs = op_succ / op_succ.sum()
                probs = np.maximum(probs, 0.08)
                probs = probs / probs.sum()

                children, parent_y, ops = [], [], []
                for _ in range(P):
                    if self.calls + len(children) >= self.budget:
                        break
                    ya, pa = pop[np.random.randint(m)]
                    pb = pop[np.random.randint(len(pop))][1]
                    child = pa.copy()
                    op = int(np.random.choice(4, p=probs))
                    if op == 3:
                        mask = np.random.rand(d) < 0.5
                        child[mask] = pb[mask]
                    if ncont:
                        if op == 2 or op == 3 or len(pop) < 3:
                            child[cont] = pa[cont] + sigma * np.random.randn(ncont)
                        else:
                            r1, r2 = np.random.choice(len(pop), 2, replace=False)
                            F = np.random.uniform(0.4, 0.9)
                            diff = pop[r1][1][cont] - pop[r2][1][cont]
                            cr = np.random.rand(ncont) < 0.9
                            if op == 0:
                                base = pa[cont] + F * diff + 0.5 * np.random.rand() * (pop[0][1][cont] - pa[cont])
                            else:
                                base = pa[cont] + F * diff
                            child[cont] = np.where(cr, base, child[cont])
                        child[cont] = np.clip(child[cont], 0.0, 1.0)

                    mutate_disc(child, pm)
                    children.append(child)
                    parent_y.append(ya)
                    ops.append(op)

                if not children:
                    break
                ys = eval_batch(children)

                success = 0
                succ_op = np.zeros(4)
                newpop = []
                for c, ya, op, y in zip(children, parent_y, ops, ys):
                    if y is None:
                        continue
                    newpop.append((y, c))
                    if y < ya:
                        success += 1
                        succ_op[op] += 1

                op_succ = 0.8 * op_succ + succ_op + 0.1
                pop = pop + newpop
                pop.sort(key=lambda t: t[0])
                pop = pop[:P]

                rate = success / max(1, len(newpop))
                if rate > 0.2:
                    sigma *= 1.2
                elif rate < 0.2:
                    sigma *= 0.85
                sigma = float(np.clip(sigma, 1e-4, 0.5))

                new_best = pop[0][0]
                if new_best < run_best - 1e-12:
                    run_best = new_best
                    stall = 0
                    swept = False
                else:
                    stall += 1

                if stall >= 4 and not swept and best_g is not None and self.calls < self.budget:
                    swept = True
                    g_s, y_s = pattern(best_g, best_y)
                    if y_s < run_best - 1e-12:
                        run_best = y_s
                        pop.append((y_s, g_s))
                        pop.sort(key=lambda t: t[0])
                        pop = pop[:P]
                        stall = 0
                        swept = False

            restarts += 1
            if self.calls == calls_before and attempts >= max_attempts:
                break

        return best_y, best_x
